  const [tab, setTab] = useState<Tab>('reconciliation'); const [prototypeTab, setPrototypeTab] = useState<PrototypeFinanceTab>('payouts'); const [rows, setRows] = useState<Batch[]>([]); const [invoices, setInvoices] = useState<CommissionInvoice[]>([]); const [invoiceBatchId, setInvoiceBatchId] = useState(''); const [vendors, setVendors] = useState<Vendor[]>([]); const [holds, setHolds] = useState<Hold[]>([]); const [events, setEvents] = useState<Event[]>([]); const [liabilities, setLiabilities] = useState<Liability[]>([]); const [payouts, setPayouts] = useState<Payout[]>([]); const [policies, setPolicies] = useState<any[]>([]); const [config, setConfig] = useState<any>(null); const [walletLedger, setWalletLedger] = useState<AgentWalletLedgerRow[]>([]); const [agentBalances, setAgentBalances] = useState<any[]>([]); const [walletCreditApprovals, setWalletCreditApprovals] = useState<WalletCreditApproval[]>([]); const [refundRows, setRefundRows] = useState<PrototypeRefund[]>([]); const [error, setError] = useState(''); const [loading, setLoading] = useState(true); const [busy, setBusy] = useState(false);
  const [outletId, setOutletId] = useState(''); const [outlets, setOutlets] = useState<Array<{id: string; name: string; status: string}>>([]); const [vendorId, setVendorId] = useState(''); const [currency, setCurrency] = useState('INR'); const [preview, setPreview] = useState<any>(null); const [selectedSourceEventIds, setSelectedSourceEventIds] = useState<Set<string>>(new Set()); const [payoutAction, setPayoutAction] = useState<PayoutAction>(null); const [activePayout, setActivePayout] = useState<Payout | null>(null); const [activeLiability, setActiveLiability] = useState<Liability | null>(null); const [reasonAction, setReasonAction] = useState<FinanceReasonAction | null>(null);
  const [adjustmentOutletId, setAdjustmentOutletId] = useState(''); const [adjustmentOutlets, setAdjustmentOutlets] = useState<Array<{id: string; name: string}>>([]); const [holdScope, setHoldScope] = useState('VENDOR'); const [holdTarget, setHoldTarget] = useState(''); const [holdReason, setHoldReason] = useState(''); const [adjustment, setAdjustment] = useState({ vendorTenantId: '', bookingId: '', signedAmount: '-100.00', currency: 'INR', reason: '', reference: '' }); const [policy, setPolicy] = useState({ cycleMode: 'MANUAL', eligibilityTrigger: 'BOOKING_CONFIRMED', settlementDelayDays: '0', weeklyDay: '', active: false, reviewRequired: true });
  async function load() { setError(''); try { const result = await Promise.all([api.request<Batch[]>('/admin/settlements'), api.request<any[]>('/admin/vendors'), api.request<Hold[]>('/admin/settlement-holds'), api.request<Event[]>('/admin/financial-events'), api.request<Liability[]>('/admin/cancellations'), api.request<Payout[]>('/admin/payouts'), api.request<any[]>('/admin/vendor-settlement-policies'), api.request<any>('/admin/finance/configuration'), api.request<AgentWalletLedgerRow[]>('/admin/agent-wallet-ledger'), api.request<any[]>('/admin/agents'), api.request<PrototypeRefund[]>('/admin/refunds'), api.request<WalletCreditApproval[]>('/admin/approvals?type=AGENT_WALLET_CREDIT'), api.request<CommissionInvoice[]>('/admin/commission-invoices')]); setRows(result[0]); setInvoices(result[12]); setVendors(result[1].map((v: any) => { const bankProof = v.vendorDocuments?.find((document: any) => document.type === 'BANK_PROOF'); const bankVerificationStatus = bankProof?.versions?.[0]?.status || bankProof?.currentStatus || null; return { id: v.id, name: v.name || v.vendorProfile?.legalBusinessName || v.id, vendorProfile: v.vendorProfile, bankVerificationStatus }; })); setHolds(result[2]); setEvents(result[3].filter((e) => ['BOOKING_CONFIRMED', 'VENDOR_ADJUSTMENT'].includes(e.type))); setLiabilities(result[4].filter((row) => !row.vendorSettlementResolved)); setPayouts(result[5]); setPolicies(result[6]); setConfig(result[7]); setWalletLedger(result[8]); setAgentBalances(result[9]); setRefundRows(result[10]); setWalletCreditApprovals(result[11]); } catch (e) { setError(e instanceof Error ? e.message : String(e)); } finally { setLoading(false); } }
  useEffect(() => { void load(); }, []); useEffect(() => { const selected = policies.find((p) => p.vendorTenantId === vendorId); if (selected) setPolicy({ cycleMode: selected.cycleMode, eligibilityTrigger: selected.eligibilityTrigger, settlementDelayDays: String(selected.settlementDelayDays), weeklyDay: selected.weeklyDay == null ? '' : String(selected.weeklyDay), active: selected.active, reviewRequired: selected.reviewRequired }); }, [vendorId, policies]);
  useEffect(() => { let cancelled = false; setOutlets([]); setOutletId(''); setPreview(null); if (vendorId) api.request<Array<{id: string; name: string; status: string}>>(`/vendor/admin/vendors/${vendorId}/outlets`).then((items) => { if (!cancelled) { setOutlets(items); if (items.length === 1) setOutletId(items[0].id); } }).catch((e) => { if (!cancelled) setError(String(e)); }); return () => { cancelled = true; }; }, [vendorId]);
