  const selectedPolicy = policies.find((p) => p.vendorTenantId === vendorId); const metricsByCurrency = useMemo(() => { const result: Record<string, number> = {}; for (const row of rows.filter((r) => ['READY_FOR_PAYOUT', 'PAYOUT_BLOCKED'].includes(r.status))) result[row.currency] = (result[row.currency] || 0) + Number(row.netPayable); return result; }, [rows]); const metricMoney = Object.entries(metricsByCurrency).map(([code, value]) => money(value, code)).join(' · ') || '—';
  async function run(action: () => Promise<unknown>) { setBusy(true); setError(''); try { await action(); await load(); } catch (e) { setError(e instanceof Error ? e.message : String(e)); } finally { setBusy(false); } }
  async function runPreview() { setBusy(true); setError(''); try { const result: any = await post('/admin/settlements/preview', { vendorTenantId: vendorId, outletId: outletId || undefined, currency }); setPreview(result); setSelectedSourceEventIds(new Set(result.eligibleLines.flatMap((line: any) => line.sourceEventIds))); } catch (e) { setError(e instanceof Error ? e.message : String(e)); } finally { setBusy(false); } }
